```python
class Solution:
    def buyChoco(self, prices: List[int], money: int) -> int:
        # Find the two smallest prices
        min1 = float('inf')
        min2 = float('inf')

        for price in prices:
            if price < min1:
                min2 = min1
                min1 = price
            elif price < min2:
                min2 = price

        total_cost = min1 + min2

        # Check if we can afford the two cheapest chocolates
        if money >= total_cost:
            return money - total_cost
        else:
            return money
